// TSAuthPort is ts-auth's plain-HTTP port on the controllers. The public API
// load balancer in the public API subnet reaches it through one exact
// controller NSG rule.
const TSAuthPort = 8080

func validateBoundary(sec Object, network netip.Prefix, gateway, public Object) {
	source := ""
	if gateway != nil {
		source = text(gateway["private_ip"]) + "/32"
	}
	ports := map[string][]int{"nsg_rules": {22, 4222}, "workload_nsg_rules": {22, 9465}}
	for _, key := range ingressLists {
		for _, v := range arr(sec[key]) {
			r := obj(v)
			if r["direction"] != "INGRESS" || r["source_type"] != "CIDR_BLOCK" || truth(r["stateless"]) || r["destination"] != nil || r["destination_type"] != nil {
				fail("manual plan " + key + " must hold stateful CIDR ingress rules only")
			}
			if source != "" && r["source"] == source {
				allowed := false
				for _, port := range ports[key] {
					allowed = allowed || eq(r["tcp_min"], port)
				}
				if !allowed || r["protocol"] != "6" || !eq(r["tcp_min"], r["tcp_max"]) {
					fail("manual plan " + key + " admits the operator gateway outside its allowed ports")
				}
			} else if !within(r["source"], network) {
				fail("manual plan " + key + " admits a source outside the private cell")
			} else if public != nil {
				if _, flexible := public["max_mbps"]; !flexible && tsAuthBackendRule(key, r, public) {
					fail("manual legacy public API must not admit the ts-auth controller port")
				}
				p, _ := prefix(public["subnet_cidr"])
				s, _ := prefix(r["source"])
				// Members, or a colocated cell's controllers, serve the
				// client port to the load balancer.
				if p.Overlaps(s) && !tsAuthBackendRule(key, r, public) && (r["source"] != public["subnet_cidr"] || r["protocol"] != "6" || !eq(r["tcp_min"], public["client_port"]) || !eq(r["tcp_max"], public["client_port"])) {
					fail("manual plan " + key + " admits the public API subnet beyond the member client port")
				}
			}
		}
	}

func tsAuthBackendRule(key string, r, public Object) bool {
	port := func(want int) bool { return eq(r["tcp_min"], want) && eq(r["tcp_max"], want) }
	return key == "nsg_rules" && r["source"] == public["subnet_cidr"] && r["protocol"] == "6" &&
		(port(TSAuthPort) || public["orch"] == true && port(publicapi.OrchPort))
}

func (e *Engine) loadPlan(path string) Object {
	p := readJSON(path, 64*1024, "manual region plan")
	p["_source_path"] = Path(must(filepath.Abs(path)))
	return validatePlan(p)
}

func validatePlan(p Object) Object {
	if !eq(p["schema_version"], 2) || catalog.OCIRegion(text(p["cell"])) == "" || p["region"] != catalog.OCIRegion(text(p["cell"])) {
		fail("unexpected manual plan schema, cell, or OCI region")
	}
	names := obj(p["preview_compartment_names"])
	if !exact(names, "control", "network", "workload") {
		fail("manual compartment names must be distinct safe names for control, network, and workload")
	}
	seen := map[string]bool{}
	for _, v := range names {
		if !safeMatch(`[A-Za-z0-9._-]{1,100}`, v) || seen[text(v)] {
			fail("manual compartment names must be distinct safe names for control, network, and workload")
		}
		seen[text(v)] = true
	}
	hosts, ok := p["hosts"].([]any)
	if !ok || len(hosts) == 0 {
		fail("manual plan must define at least one host")
	}
	slots, members := []string{}, []string{}
	controllers := 0
	seen = map[string]bool{}
	for _, v := range hosts {
		h, ok := v.(Object)
		if !ok || seen[text(h["slot"])] {
			fail("manual host slots must be unique objects")
		}
		slot := text(h["slot"])
		seen[slot] = true
		slots = append(slots, slot)
		if strings.HasPrefix(slot, "controller-") {
			controllers++
		} else if strings.HasPrefix(slot, "member-") {
			members = append(members, slot)
		}
	}
	if !eq(controllers, p["controller_replicas"]) || !eq(len(members), p["database_members"]) || controllers+len(members) != len(hosts) {
		fail("manual host roster differs from its controller and database member counts")
	}
	for _, v := range hosts {
		h := obj(v)
		slot := text(h["slot"])

gateway := validateGateway(p, network)
if ids["local_peering_gateway"] != nil && gateway == nil {
	fail("manual cell peering gateway requires a declared operator gateway")
}
public := validatePublic(p, network, subnet)
if public == nil {
	for key := range publicIDs {
		if ids[key] != nil {
			fail("manual public API resources require a declared public API")
		}
	}
}
sec := obj(p["network_security"])
if !exact(sec, "nsg_rules", "workload_nsg_rules", "security_list_ingress_rules", "security_list_egress_rules", "route_rules", "service_gateway_service_id", "service_gateway_cidr_block") {
	fail("manual plan must declare exact network and security state")
}
for _, key := range append(append([]string{}, ingressLists...), "security_list_egress_rules") {
	validateRules(sec[key], key)
}
validateBoundary(sec, network, gateway, public)

func LoadPlan(path string) (Object, error) {
	e := &Engine{PlanPath: path}
	return capture(func() Object { return e.loadPlan(path) })
}

func readJSON(path string, limit int, label string) Object {
	wire := readBytes(path, limit, label)
	v, err := decodeJSON(wire)
	if err != nil {
		if strings.Contains(err.Error(), "duplicate") {
			fail("JSON document has duplicate fields")
		}
		fail(label + " is unreadable or invalid JSON")
	}
	m, ok := v.(map[string]any)
	if !ok {
		fail(label + " must be an object")
	}
	return m
}

func capture[T any](fn func() T) (v T, err error) {
	defer func() {
		if r := recover(); r != nil {
			if e, ok := r.(error); ok {
				err = e
			} else {
				err = fmt.Errorf("%v", r)
			}
		}
	}()
	return fn(), nil
}

bucket_fixture.text:
var (
	key   = ociresource.Key{Region: "GRU", Kind: Kind, Name: "backups"}
	owner = ociresource.Ownership{Mode: ociresource.TagModeFreeform, Owner: "cell-gru"}
)

type providerState struct {
	bucket       Bucket
	rules        []Rule
	calls        []string
	nextID       int
	api          API
	loseResponse bool
}

func (f *providerState) GetBucket(context.Context, string, string) (Bucket, error) {
	return f.bucket, nil
}
func (f *providerState) ListRetentionRules(context.Context, string, string) ([]Rule, error) {
	return slices.Clone(f.rules), nil
}
func (f *providerState) UpdateBucket(_ context.Context, _, _, etag, versioning string, tags ociresource.Tags) error {
	if etag != f.bucket.ETag {
		return errors.New("etag mismatch")
	}
	if versioning == VersioningEnabled && len(f.rules) > 0 {
		return errors.New("versioning refused with retention rules")
	}
	f.calls = append(f.calls, "bucket "+versioning)
	if versioning != "" {
		f.bucket.Versioning = versioning
	}
	f.bucket.Tags, f.bucket.ETag = tags, etag+"'"
	return nil
}
func (f *providerState) CreateRetentionRule(_ context.Context, _, _, name string, amount int64, unit string) error {
	if f.bucket.Versioning == VersioningEnabled {
		return errors.New("retention refused on a versioned bucket")
	}
	f.nextID++
	f.calls = append(f.calls, "create "+name)
	f.rules = append(f.rules, Rule{ID: fmt.Sprintf("r%d", f.nextID), DisplayName: name, ETag: "r", Amount: amount, Unit: unit})
	f.bucket.ETag += "+"
	return nil
}
func (f *providerState) UpdateRetentionRule(_ context.Context, _, _, id, _ string, amount int64, unit string) error {
	f.calls = append(f.calls, "update "+id)
	for index := range f.rules {
		if f.rules[index].ID == id {
			if f.rules[index].Locked {
				return errors.New("locked")
			}
			f.rules[index].Amount, f.rules[index].Unit = amount, unit
		}
	}
	return nil
}
func (f *providerState) DeleteRetentionRule(_ context.Context, _, _, id, _ string) error {
	f.calls = append(f.calls, "delete "+id)
	f.rules = slices.DeleteFunc(f.rules, func(rule Rule) bool { return rule.ID == id })
	f.bucket.ETag += "-"
	return nil
}

type allow struct{}

func (allow) Guard(context.Context, uint64) error { return nil }

func ownedBucket() Bucket {
	return Bucket{Namespace: "tenancy", Name: "backups", ETag: "b1", Versioning: VersioningDisabled,
		Tags: ociresource.Tags{Freeform: map[string]string{"team": "data"}}.Merge(owner.Stamp(key, 0, ""))}
}

func reconcile(t *testing.T, api *providerState, store ociresource.Store, spec Spec, policy ociresource.DriftPolicy) (ociresource.Result, error) {
	t.Helper()
	confirm(t, api, store)
	if _, err := ociresource.Publish(t.Context(), store, key, policy, spec); err != nil {
		t.Fatal(err)
	}
	controller := &ociresource.Controller[Spec, Observed]{Region: "GRU", Resource: Reconciler{API: api.client(t)}, Store: store,
		Ownership: owner, Authority: allow{}}
	return controller.Reconcile(t.Context(), 1)
}

func (f *providerState) client(t *testing.T) API {
	t.Helper()
	if f.api != nil {
		return f.api
	}
	factory, endpoint := ociresourcetest.Server(t, func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		var err error
		mutation := r.Method != http.MethodGet
		retention := strings.Contains(r.URL.Path, "/retentionRules")
		id := r.URL.Path[strings.LastIndex(r.URL.Path, "/")+1:]
		if mutation {
			body, readErr := io.ReadAll(r.Body)
			if readErr != nil {
				t.Error(readErr)
				w.WriteHeader(400)
				return
			}
			switch {
			case !retention && r.Method == http.MethodPost:
				var details objectstorage.UpdateBucketDetails
				if err = json.Unmarshal(body, &details); err == nil {
					err = f.UpdateBucket(r.Context(), "tenancy", "backups", r.Header.Get("if-match"), string(details.Versioning), ociresource.Tags{Freeform: details.FreeformTags, Defined: details.DefinedTags})
				}
			case retention && r.Method == http.MethodPost:
				var details objectstorage.CreateRetentionRuleDetails
				if err = json.Unmarshal(body, &details); err == nil {
					if details.TimeRuleLocked != nil {
						t.Error("controller attempted to lock retention")
					}
					if details.Duration == nil {
						err = errors.New("duration required")
					} else {
						err = f.CreateRetentionRule(r.Context(), "tenancy", "backups", deref(details.DisplayName), *details.Duration.TimeAmount, string(details.Duration.TimeUnit))
					}
				}
			case retention && (r.Method == http.MethodPut || r.Method == http.MethodDelete):
				found := false
				for _, rule := range f.rules {
					if rule.ID == id {
						found = true
						if rule.ETag != r.Header.Get("if-match") {
							err = errors.New("etag mismatch")
						}
						if rule.Locked {
							err = errors.New("locked")
						}
					}
				}
				if !found {
					err = errors.New("retention rule not found")
				}
				if err == nil && r.Method == http.MethodDelete {
					err = f.DeleteRetentionRule(r.Context(), "tenancy", "backups", id, r.Header.Get("if-match"))
				} else if err == nil {
					var details objectstorage.UpdateRetentionRuleDetails
					if err = json.Unmarshal(body, &details); err == nil {
						if details.TimeRuleLocked != nil {
							t.Error("controller attempted to lock retention")
						}
						if details.Duration == nil {
							err = errors.New("duration required")
						} else {
							err = f.UpdateRetentionRule(r.Context(), "tenancy", "backups", id, r.Header.Get("if-match"), *details.Duration.TimeAmount, string(details.Duration.TimeUnit))
						}
					}
				}
			default:
				t.Errorf("unexpected %s %s", r.Method, r.URL.Path)
				w.WriteHeader(405)
				return
			}
			if err != nil {
				w.WriteHeader(http.StatusPreconditionFailed)
				body, _ := json.Marshal(map[string]string{"code": "NoEtagMatch", "message": err.Error()})
				_, _ = w.Write(body)
				return
			}
			if f.loseResponse {
				f.loseResponse = false
				connection, _, hijackErr := w.(http.Hijacker).Hijack()
				if hijackErr != nil {
					t.Error(hijackErr)
					return
				}
				_ = connection.Close()
				return
			}
		}
		timestamp := &common.SDKTime{Time: time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)}
		var response any
		if retention {
			rules := []objectstorage.RetentionRuleSummary{}
			for _, rule := range f.rules {
				item := objectstorage.RetentionRuleSummary{Id: new(rule.ID), DisplayName: new(rule.DisplayName), Etag: new(rule.ETag), Duration: duration(rule.Amount, rule.Unit), TimeCreated: timestamp, TimeModified: timestamp}
				if rule.Locked {
					item.TimeRuleLocked = timestamp
				}
				rules = append(rules, item)
			}
			if r.Method == http.MethodGet {
				response = map[string]any{"items": rules}
			} else if len(rules) > 0 {
				response = rules[len(rules)-1]
			} else {
				response = map[string]any{}
			}
		} else {
			w.Header().Set("etag", f.bucket.ETag)
			response = objectstorage.Bucket{Namespace: new(f.bucket.Namespace), Name: new(f.bucket.Name), Etag: new(f.bucket.ETag), Versioning: objectstorage.BucketVersioningEnum(f.bucket.Versioning), FreeformTags: f.bucket.Tags.Freeform, DefinedTags: f.bucket.Tags.Defined, TimeCreated: timestamp}
		}
		if r.Method == http.MethodDelete {
			w.WriteHeader(http.StatusNoContent)
			return
		}
		body, marshalErr := json.Marshal(response)
		if marshalErr != nil {
			t.Error(marshalErr)
			w.WriteHeader(500)
			return
		}
		_, _ = w.Write(body)
	})
	api, err := newSDKAPI(factory, endpoint)
	if err != nil {
		t.Fatal(err)
	}
	f.api = api
	return api
}

func persistentStore(t *testing.T) *ociresource.KVStore {
	t.Helper()
	return ociresourcetest.Store(t)
}

func confirm(t *testing.T, api *providerState, store ociresource.Store) {
	t.Helper()
	current, err := store.Get(t.Context(), key)
	if errors.Is(err, ociresource.ErrNotFound) {
		return
	}
	if err != nil {
		t.Fatal(err)
	}
	if current.Operation == nil || !current.Operation.CompletedAt.IsZero() {
		return
	}
	controller := &ociresource.Controller[Spec, Observed]{Region: "GRU", Resource: Reconciler{API: api.client(t)}, Store: store, Ownership: owner, Authority: allow{}}
	result, err := controller.Reconcile(t.Context(), 1)
	if err != nil || result.InSync != 1 {
		t.Fatalf("confirm=%+v err=%v", result, err)
	}
}

// Package ociresourcetest serves reconciler SDK tests: a signed-request
// factory and a loopback server standing in for one OCI service. No
// production binary links it.
package ociresourcetest

import (
	"crypto/rand"
	"crypto/rsa"
	"crypto/x509"
	"encoding/pem"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/oracle/oci-go-sdk/v65/common"

	"github.com/TerraScale/ts-orchestrator/internal/ociclient"
)

// Region is the catalog region the test factory is pinned to.
const Region = "sa-saopaulo-1"

// Server starts handler on loopback and returns a factory and its URL. Every
// request the handler sees must be signed.
func Server(t *testing.T, handler http.HandlerFunc) (*ociclient.Factory, string) {
	t.Helper()
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	provider := common.NewRawConfigurationProvider("ocid1.tenancy.oc1..t", "ocid1.user.oc1..u", Region, "fp",
		string(pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})), nil)
	factory, err := ociclient.New(provider, ociclient.Options{Region: Region})
	if err != nil {
		t.Fatal(err)
	}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("Authorization") == "" {
			t.Errorf("unsigned %s %s", r.Method, r.URL.Path)
			http.Error(w, "unsigned", http.StatusUnauthorized)
			return
		}
		handler(w, r)
	}))
	t.Cleanup(server.Close)
	return factory, server.URL
}

