func newSDKAPI(factory *ociclient.Factory, endpoint string) (API, error) {
	objects, err := factory.ObjectStorage()
	if err != nil {
		return nil, err
	}
	ociclient.PinHost(&objects.BaseClient, endpoint)
	return sdkAPI{objects: objects}, nil
}

func deref(value *string) string {
	if value == nil {
		return ""
	}
	return *value
}

func notFound(err error) bool {
	serviceErr, ok := common.IsServiceError(err)
	return ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound
}

func (a sdkAPI) GetBucket(ctx context.Context, namespace, bucket string) (Bucket, error) {
	response, err := a.objects.GetBucket(ociclient.RequestContext(ctx), objectstorage.GetBucketRequest{NamespaceName: new(namespace), BucketName: new(bucket)})
	if err != nil {
		if notFound(err) {
			return Bucket{}, fmt.Errorf("get OCI bucket: %w: %w", ociresource.ErrGone, err)
		}
		return Bucket{}, fmt.Errorf("get OCI bucket: %w", err)
	}
	etag := deref(response.ETag)
	if etag == "" {
		etag = deref(response.Etag)
	}
	return Bucket{Namespace: deref(response.Namespace), Name: deref(response.Name), ETag: etag,
		Versioning: string(response.Versioning),
		Tags:       ociresource.Tags{Freeform: response.FreeformTags, Defined: response.DefinedTags}}, nil
}

func (a sdkAPI) ListRetentionRules(ctx context.Context, namespace, bucket string) ([]Rule, error) {
	var rules []Rule
	var page *string
	for range maxPages {
		response, err := a.objects.ListRetentionRules(ociclient.RequestContext(ctx), objectstorage.ListRetentionRulesRequest{
			NamespaceName: new(namespace), BucketName: new(bucket), Page: page})
		if err != nil {
			return nil, fmt.Errorf("list OCI retention rules: %w", err)
		}
		for _, item := range response.Items {
			rule := Rule{ID: deref(item.Id), DisplayName: deref(item.DisplayName), ETag: deref(item.Etag),
				Locked: item.TimeRuleLocked != nil}
			if item.Duration != nil && item.Duration.TimeAmount != nil {
				rule.Amount, rule.Unit = *item.Duration.TimeAmount, string(item.Duration.TimeUnit)
			}
			rules = append(rules, rule)
		}
		if response.OpcNextPage == nil || *response.OpcNextPage == "" {
			return rules, nil
		}
		page = response.OpcNextPage
	}
	return nil, errors.New("OCI retention rule list exceeds its page bound")
}

func (a sdkAPI) UpdateBucket(ctx context.Context, namespace, bucket, etag, versioning string, tags ociresource.Tags) error {
	if etag == "" {
		return errors.New("update OCI bucket requires an ETag")
	}
	details := objectstorage.UpdateBucketDetails{FreeformTags: maps.Clone(tags.Freeform), DefinedTags: tags.Defined,
		Versioning: objectstorage.UpdateBucketDetailsVersioningEnum(versioning)}
	if _, err := a.objects.UpdateBucket(ociclient.RequestContext(ctx), objectstorage.UpdateBucketRequest{NamespaceName: new(namespace),
		BucketName: new(bucket), IfMatch: new(etag), UpdateBucketDetails: details}); err != nil {
		return fmt.Errorf("update OCI bucket: %w", err)
	}
	return nil
}

func duration(amount int64, unit string) *objectstorage.Duration {
	return &objectstorage.Duration{TimeAmount: new(amount), TimeUnit: objectstorage.DurationTimeUnitEnum(unit)}
}

func (a sdkAPI) CreateRetentionRule(ctx context.Context, namespace, bucket, displayName string, amount int64, unit string) error {
	// TimeRuleLocked stays unset: the reconciler never locks a rule.
	if _, err := a.objects.CreateRetentionRule(ociclient.RequestContext(ctx), objectstorage.CreateRetentionRuleRequest{NamespaceName: new(namespace),
		BucketName: new(bucket), CreateRetentionRuleDetails: objectstorage.CreateRetentionRuleDetails{
			DisplayName: new(displayName), Duration: duration(amount, unit)}}); err != nil {
		return fmt.Errorf("create OCI retention rule: %w", err)
	}
	return nil
}

func (a sdkAPI) UpdateRetentionRule(ctx context.Context, namespace, bucket, id, etag string, amount int64, unit string) error {
	request := objectstorage.UpdateRetentionRuleRequest{NamespaceName: new(namespace), BucketName: new(bucket),
		RetentionRuleId: new(id), UpdateRetentionRuleDetails: objectstorage.UpdateRetentionRuleDetails{Duration: duration(amount, unit)}}
	if etag != "" {
		request.IfMatch = new(etag)
	}
	if _, err := a.objects.UpdateRetentionRule(ociclient.RequestContext(ctx), request); err != nil {
		return fmt.Errorf("update OCI retention rule: %w", err)
	}
	return nil
}

func (a sdkAPI) DeleteRetentionRule(ctx context.Context, namespace, bucket, id, etag string) error {
	request := objectstorage.DeleteRetentionRuleRequest{NamespaceName: new(namespace), BucketName: new(bucket),
		RetentionRuleId: new(id)}
	if etag != "" {
		request.IfMatch = new(etag)
	}
	_, err := a.objects.DeleteRetentionRule(ociclient.RequestContext(ctx), request)
	if err != nil && !notFound(err) {
		return fmt.Errorf("delete OCI retention rule: %w", err)
	}
	return nil
}

func New(provider common.ConfigurationProvider, options Options) (*Factory, error) {
	if provider == nil {
		return nil, errors.New("OCI client factory requires a configuration provider")
	}
	if !catalog.IsOCIRegion(options.Region) {
		return nil, fmt.Errorf("OCI client factory region %q is not in the region catalog", options.Region)
	}
	limits := make(map[Service]Limit, len(DefaultLimits))
	for service, limit := range DefaultLimits {
		limits[service] = limit
	}
	for service, limit := range options.Limits {
		if limit.PerSecond <= 0 || limit.Burst < 1 {
			return nil, fmt.Errorf("OCI client limit for %s must be positive", service)
		}
		limits[service] = limit
	}
	return &Factory{provider: provider, region: options.Region, limits: limits,
		policy: RetryPolicy(options.Retry), limiters: map[Service]*rate.Limiter{}}, nil
}

func (f *Factory) Configure(client *common.BaseClient, service Service) {
	limiter := f.Limiter(service)
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		ctx := request.Context()
		if ctx == nil {
			ctx = context.Background()
		}
		if err := limiter.Wait(ctx); err != nil {
			return fmt.Errorf("OCI %s rate limiter: %w", service, err)
		}
		if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
			if guard, ok := ctx.Value(authorityKey{}).(func(context.Context) error); ok {
				if err := guard(ctx); err != nil {
					return fmt.Errorf("OCI %s write authority: %w", service, err)
				}
			}
		}
		if previous != nil {
			return previous(request)
		}
		return nil
	}
	policy := f.policy
	// Set only the retry policy: replacing the whole configuration would drop
	// a circuit breaker the SDK installed from OCI_SDK_DEFAULT_CIRCUITBREAKER_ENABLED
	// or its global setting.
	client.Configuration.RetryPolicy = &policy
	ConfigureReadCancellation(client)
}

// PinHost replaces a client's endpoint with an exact canonical endpoint. It is
// used by callers whose signed configuration names the endpoint.
func PinHost(client *common.BaseClient, endpoint string) {
	if endpoint = strings.TrimSuffix(endpoint, "/"); endpoint != "" {
		client.Host = endpoint
	}
}

func (f *Factory) ObjectStorage() (objectstorage.ObjectStorageClient, error) {
	client, err := objectstorage.NewObjectStorageClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI Object Storage client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceObjectStorage)
	client.HTTPClient = Instrument(client.HTTPClient, string(ServiceObjectStorage))
	return client, nil
}

func Instrument(next common.HTTPRequestDispatcher, service string) common.HTTPRequestDispatcher {
	if next == nil {
		next = http.DefaultClient
	}
	return &instrumentedDispatcher{next: next, service: service, now: time.Now}
}

func (dispatcher *instrumentedDispatcher) Do(request *http.Request) (*http.Response, error) {
	started := dispatcher.now()
	response, err := dispatcher.next.Do(request)
	elapsed := dispatcher.now().Sub(started)
	status := 0
	if response != nil {
		status = response.StatusCode
	}
	apiStats.record(dispatcher.service, operationTemplate(request), status, err != nil, elapsed)
	return response, err
}
